const STATUS_CLASS_MAP: Record<EstatusSolicitudBackend, string> = {
  Enviada: 'bg-info text-dark',
  Incompleta: 'bg-warning text-dark',
  Subsanada: 'bg-warning text-dark',
  'No Presentada': 'bg-secondary',
  'En Dictaminación': 'bg-primary',
  Autorizada: 'bg-success',
  'En Seguimiento': 'bg-info text-dark',
  Aprobada: 'bg-success',
  'No Aprobada': 'bg-danger',
  'No Autorizada': 'bg-danger',
  Suspendida: 'bg-secondary',
  Revocada: 'bg-danger',
  'En Análisis': 'bg-info text-dark',
  'En Firma': 'bg-warning text-dark',
  Terminada: 'bg-success',
};

export function statusToClass(status: string): string {
  return STATUS_CLASS_MAP[status as EstatusSolicitudBackend] ?? 'bg-secondary';
}

export function semaforoColorClass(color: string): string {
  const map: Record<string, string> = {
    verde: 'bg-success',
    amarillo: 'bg-warning',
    naranja: 'bg-orange',
    rojo: 'bg-danger',
  };
  return map[color] ?? 'bg-secondary';
}

export function semaforoBadgeClass(color: string): string {
  const bg = semaforoColorClass(color);
  const textMap: Record<string, string> = {
    verde: 'text-white',
    amarillo: 'text-dark',
    naranja: 'text-white',
    rojo: 'text-white',
  };
  const text = textMap[color] ?? 'text-white';
  return `${bg} ${text}`;
}
